-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (소식 표·방·날 표의 줄 수와 권한·정책 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261027200000' and name='tg_summary_edit')=1 then '예' else '아니오' end as value
union all select 'two new tables: RLS on, one read policy each (authenticated, owner check)',case when (select count(*) from pg_class where oid in(to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and relrowsecurity and not relforcerowsecurity and coalesce(relacl::text,'')!~'(^|[{,])(anon)?=')=2 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and polcmd='r' and polroles=array['authenticated'::regrole]::oid[] and pg_get_expr(polqual,polrelid) like '%app_is_workspace_owner%')=2 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')))=2 then '예' else '아니오' end
union all select 'new tables: authenticated reads only, service_role and anon nothing',case when has_table_privilege('authenticated','public.app_feed_summary_edits','select') and has_table_privilege('authenticated','public.app_feed_summary_edit_history','select') and not has_table_privilege('authenticated','public.app_feed_summary_edits','insert') and not has_table_privilege('authenticated','public.app_feed_summary_edits','update') and not has_table_privilege('authenticated','public.app_feed_summary_edits','delete') and not has_table_privilege('authenticated','public.app_feed_summary_edit_history','insert') and not has_table_privilege('authenticated','public.app_feed_summary_edit_history','update') and not has_table_privilege('authenticated','public.app_feed_summary_edit_history','delete') and not has_any_column_privilege('service_role','public.app_feed_summary_edits','select') and not has_any_column_privilege('service_role','public.app_feed_summary_edit_history','select') and not has_any_column_privilege('anon','public.app_feed_summary_edits','select') and not has_any_column_privilege('anon','public.app_feed_summary_edit_history','select') then '예' else '아니오' end
union all select 'function: definer, empty search_path, execute only authenticated',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_feed_summary_edit(uuid,text,date,jsonb)') and p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'new tables start empty',case when not exists(select 1 from public.app_feed_summary_edits) and not exists(select 1 from public.app_feed_summary_edit_history) then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the feed tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'room days rows',(select count(*)::text from public.app_feed_room_days)
union all select 'feed tables grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_room_days')) ),'')
  ||coalesce((select string_agg(c.relname::text||'.'||a.attname::text||':'||a.attacl::text,',' order by c.relname,a.attname) from pg_attribute a join pg_class c on c.oid=a.attrelid where a.attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_room_days')) and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_room_days'))),''));
